let recData = [];
let perfData = {};

try {
  recData = $node["Get Recommendations"].json.data || [];
} catch (e) {
  recData = [];
}

try {
  perfData = $node["Get Performance"].json || {};
} catch (e) {
  perfData = {};
}

const today = new Date().toISOString().split('T')[0];
let docTitle = `주간 AI 주식 추천 및 성과 보고서 (${today})`;

let html = `<!DOCTYPE html>
<html>
<head>
<meta charset='utf-8'>
<style>
  body {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    color: #334155;
    line-height: 1.6;
    margin: 20px;
  }
  h1 {
    color: #1e3a8a;
    font-size: 22px;
    border-bottom: 2px solid #3b82f6;
    padding-bottom: 8px;
    margin-bottom: 20px;
  }
  h2 {
    color: #0f172a;
    font-size: 16px;
    margin-top: 30px;
    margin-bottom: 10px;
    border-left: 4px solid #3b82f6;
    padding-left: 10px;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
  }
  th {
    background-color: #1e293b;
    color: #ffffff;
    font-weight: bold;
    text-align: left;
    padding: 10px;
    font-size: 12px;
  }
  td {
    padding: 10px;
    border-bottom: 1px solid #e2e8f0;
    font-size: 12px;
  }
  .center {
    text-align: center;
  }
  .bold {
    font-weight: bold;
  }
  .green {
    color: #16a34a;
    font-weight: bold;
  }
  .red {
    color: #dc2626;
    font-weight: bold;
  }
  .summary-box {
    background-color: #f8fafc;
    border: 1px solid #e2e8f0;
    padding: 15px;
    border-radius: 6px;
    margin-bottom: 20px;
  }
  .summary-box ul {
    margin: 0;
    padding-left: 20px;
  }
  .summary-box li {
    margin-bottom: 8px;
    font-size: 13px;
  }
</style>
</head>
<body>

<h1>주간 AI 주식 추천 및 성과 보고서 (${today})</h1>

<h2>이번 주 AI 추천 Top 10 종목</h2>
<p style='font-size: 12px; color: #64748b; margin-bottom: 10px;'>추천 기준일: ${perfData.target_date || today}</p>

<table>
  <thead>
    <tr>
      <th style='width: 8%;' class='center'>순위</th>
      <th style='width: 10%;' class='center'>티커</th>
      <th style='width: 12%;'>현재가</th>
      <th style='width: 12%;'>주간 변동률</th>
      <th style='width: 12%;' class='center'>AI 점수</th>
      <th>주요 추천 이유</th>
    </tr>
  </thead>
  <tbody>
`;

const top10 = recData.slice(0, 10);
top10.forEach(item => {
  const changeClass = item.change && item.change.startsWith('+') ? 'green' : (item.change && item.change.startsWith('-') ? 'red' : '');
  html += `    <tr>
      <td class='center bold'>${item.rank}</td>
      <td class='center bold'>${item.symbol}</td>
      <td>${item.price}</td>
      <td class='${changeClass}'>${item.change}</td>
      <td class='center'>${item.prob}</td>
      <td>${item.reason_text}</td>
    </tr>
`;
});

html += `  </tbody>
</table>

<h2>지난 주 추천 종목 성과 평가 보고서</h2>
<p style='font-size: 12px; color: #64748b; margin-bottom: 15px;'>이전 추천 기준일: ${perfData.prev_date || 'N/A'} | 평가 기준일: ${perfData.target_date || 'N/A'}</p>
`;

if (perfData.status === 'success') {
  const avgClass = perfData.avg_return && perfData.avg_return.startsWith('+') ? 'green' : (perfData.avg_return && perfData.avg_return.startsWith('-') ? 'red' : '');
  const spyClass = perfData.spy_return && perfData.spy_return.startsWith('+') ? 'green' : (perfData.spy_return && perfData.spy_return.startsWith('-') ? 'red' : '');
  const activeClass = perfData.active_return && perfData.active_return.startsWith('+') ? 'green' : (perfData.active_return && perfData.active_return.startsWith('-') ? 'red' : '');

  html += `
<div class='summary-box'>
  <p class='bold' style='margin-top: 0; margin-bottom: 10px; font-size: 14px; color: #0f172a;'>■ 성과 요약</p>
  <ul>
    <li>AI 추천주 평균 수익률: <span class='${avgClass}'>${perfData.avg_return}</span></li>
    <li>S&P 500 (SPY) 수익률: <span class='${spyClass}'>${perfData.spy_return}</span></li>
    <li>벤치마크 대비 초과 수익률: <span class='${activeClass}'>${perfData.active_return}</span></li>
  </ul>
</div>

<p class='bold' style='margin-bottom: 10px; font-size: 14px; color: #0f172a;'>■ 종목별 상세 수익률</p>
<table>
  <thead>
    <tr>
      <th style='width: 25%;' class='center'>티커</th>
      <th style='width: 25%;'>추천가</th>
      <th style='width: 25%;'>현재가</th>
      <th style='width: 25%;'>수익률</th>
    </tr>
  </thead>
  <tbody>
`;

  perfData.data.forEach(item => {
    const returnClass = item.return_pct && item.return_pct.startsWith('+') ? 'green' : (item.return_pct && item.return_pct.startsWith('-') ? 'red' : '');
    html += `    <tr>
      <td class='center bold'>${item.symbol}</td>
      <td>${item.rec_price}</td>
      <td>${item.current_price}</td>
      <td class='${returnClass}'>${item.return_pct}</td>
    </tr>
`;
  });

  html += `  </tbody>
</table>
`;
} else {
  html += `
<div class='summary-box' style='color: #dc2626;'>
  이전 추천 데이터를 찾을 수 없어 이번 주 수익률 보고서를 생성하지 못했습니다: ${perfData.message || '캐시 없음'}
</div>
`;
}

html += `
</body>
</html>
`;

const binaryData = Buffer.from(html, 'utf-8');

return [
  {
    "json": {
      "title": docTitle
    },
    "binary": {
      "data": {
        "data": binaryData.toString('base64'),
        "mimeType": "text/html",
        "fileName": `${docTitle}.html`
      }
    }
  }
];
